
# Import dataclass to create a structured data container.
from dataclasses import dataclass


# Automatically generate a constructor for our response.
@dataclass
class ModelResponse:

    # The text returned by the AI model.
    output_text: str

    # Number of tokens sent to the model.
    input_tokens: int

    # Number of tokens generated by the model.
    output_tokens: int

    # Total time the API request took, in milliseconds.
    latency_ms: float

    # Estimated cost of this request in USD.
    cost_usd: float

    # Exact identifier of the model that answered.
    model_id: str

    # Name of the company or local provider.
    provider: str
